import { defineConfig, type UserConfig } from "tsdown";

// Anotasi tipe dibutuhkan karena tsconfig memakai isolatedDeclarations.
const config: UserConfig = defineConfig({
  entry: ["src/index.ts", "src/rupiah.ts", "src/terbilang.ts", "src/nik.ts"],
  format: ["esm", "cjs"],
  platform: "neutral",
  dts: true,
  clean: true,
});

export default config;

/**
 * Utilitas kecil untuk data khas Indonesia: Rupiah, terbilang, dan format NIK.
 *
 * @packageDocumentation
 */
export * from "./rupiah.js";
export * from "./terbilang.js";
export * from "./nik.js";

/**
 * Pilihan untuk {@link formatRupiah}.
 */
export interface OpsiFormatRupiah {
  /** Tampilkan dua angka sen di belakang koma. Bawaan: `false` (dibulatkan ke rupiah terdekat). */
  readonly sen?: boolean;
}

const tanpaSen = new Intl.NumberFormat("id-ID", {
  style: "currency",
  currency: "IDR",
  minimumFractionDigits: 0,
  maximumFractionDigits: 0,
});
const denganSen = new Intl.NumberFormat("id-ID", {
  style: "currency",
  currency: "IDR",
  minimumFractionDigits: 2,
  maximumFractionDigits: 2,
});

/**
 * Mengubah angka menjadi teks Rupiah gaya Indonesia.
 *
 * @param nilai - Jumlah uang dalam rupiah. Harus bilangan terhingga.
 * @param opsi - Pilihan tampilan.
 * @returns Teks seperti `"Rp 1.500.000"` (spasi biasa, bukan non-breaking space).
 * @throws `RangeError` kalau `nilai` adalah `NaN` atau `Infinity`.
 *
 * @example
 * ```ts
 * formatRupiah(1500000); // "Rp 1.500.000"
 * formatRupiah(-2500.5, { sen: true }); // "-Rp 2.500,50"
 * ```
 */
export function formatRupiah(nilai: number, opsi: OpsiFormatRupiah = {}): string {
  if (!Number.isFinite(nilai)) {
    throw new RangeError(`formatRupiah: nilai harus bilangan terhingga, bukan ${String(nilai)}`);
  }
  const formatter = opsi.sen === true ? denganSen : tanpaSen;
  return formatter.format(nilai).replace(/\u00a0/g, " ");
}

// Tanda minus boleh di depan atau sesudah "Rp", titik pemisah ribuan harus per 3 digit.
const POLA_RUPIAH = /^(-?)(?:rp\.?)?(-?)(\d{1,3}(?:\.\d{3})+|\d+)(?:,(\d+))?$/i;

/**
 * Membaca teks Rupiah gaya Indonesia menjadi angka.
 *
 * Menerima `"Rp 1.500.000"`, `"Rp1.500.000,50"`, `"-Rp 5.000"`, `"Rp -5.000"`, dan `"25000"`.
 * Titik selalu dibaca sebagai pemisah ribuan dan koma sebagai pemisah desimal.
 *
 * @param teks - Teks yang akan dibaca.
 * @returns Nilai dalam rupiah.
 * @throws `SyntaxError` kalau teks tidak berbentuk Rupiah, misalnya `"Rp 1.5"` atau `"satu juta"`.
 *
 * @example
 * ```ts
 * parseRupiah("Rp 1.500.000"); // 1500000
 * parseRupiah(formatRupiah(42000)); // 42000
 * ```
 */
export function parseRupiah(teks: string): number {
  const cocok = POLA_RUPIAH.exec(teks.replace(/\s/g, ""));
  if (cocok === null || (cocok[1] === "-" && cocok[2] === "-")) {
    throw new SyntaxError(`parseRupiah: format tidak dikenali: "${teks}"`);
  }
  const [, minusDepan, minusBelakang, bulat = "", pecahan] = cocok;
  const nilai = Number(bulat.replaceAll(".", "") + (pecahan === undefined ? "" : `.${pecahan}`));
  const negatif = minusDepan === "-" || minusBelakang === "-";
  return negatif && nilai !== 0 ? -nilai : nilai;
}

import { defineConfig, type ViteUserConfig } from "vitest/config";

const config: ViteUserConfig = defineConfig({
  test: {
    include: ["test/**/*.test.ts"],
    coverage: {
      provider: "v8",
      include: ["src/**/*.ts"],
      reporter: ["text", "html"],
      thresholds: { lines: 95, statements: 95, functions: 100, branches: 90 },
    },
  },
});

export default config;

import fc from "fast-check";
import { describe, expect, it } from "vitest";
import { formatRupiah, parseRupiah } from "../src/rupiah.js";

describe("formatRupiah", () => {
  it.each([
    [0, "Rp 0"],
    [1500000, "Rp 1.500.000"],
    [999, "Rp 999"],
    [-5000, "-Rp 5.000"],
    [2500.4, "Rp 2.500"],
  ])("%d menjadi %s", (nilai, harapan) => {
    expect(formatRupiah(nilai)).toBe(harapan);
  });

  it("menampilkan sen kalau diminta", () => {
    expect(formatRupiah(1234.5, { sen: true })).toBe("Rp 1.234,50");
  });

  it("menolak NaN dan Infinity", () => {
    expect(() => formatRupiah(Number.NaN)).toThrow(RangeError);
    expect(() => formatRupiah(Infinity)).toThrow(RangeError);
  });
});

describe("parseRupiah", () => {
  it.each([
    ["Rp 1.500.000", 1500000],
    ["Rp1.500.000,50", 1500000.5],
    ["rp. 25.000", 25000],
    ["25000", 25000],
    ["-Rp 5.000", -5000],
    ["Rp -5.000", -5000],
    ["-Rp 0", 0],
  ])("%s menjadi %d", (teks, harapan) => {
    expect(parseRupiah(teks)).toBe(harapan);
  });

  it.each(["", "Rp", "Rp 1.5", "1,500,000", "--Rp 5", "-Rp -5", "satu juta", "Rp 12.34.567"])(
    "menolak %j",
    (teks) => {
      expect(() => parseRupiah(teks)).toThrow(SyntaxError);
    },
  );
});

describe("properti: format lalu parse kembali ke angka semula", () => {
  it("rupiah bulat", () => {
    fc.assert(
      fc.property(fc.integer({ min: -1e15, max: 1e15 }), (n) => {
        expect(parseRupiah(formatRupiah(n))).toBe(n);
      }),
    );
  });

  it("rupiah dengan sen", () => {
    fc.assert(
      fc.property(fc.integer({ min: -1e13, max: 1e13 }), (senTotal) => {
        const nilai = senTotal / 100;
        expect(parseRupiah(formatRupiah(nilai, { sen: true }))).toBe(nilai);
      }),
    );
  });
});

const SATUAN = [
  "", "satu", "dua", "tiga", "empat", "lima", "enam", "tujuh", "delapan", "sembilan", "sepuluh", "sebelas",
] as const;
const SKALA = ["", "ribu", "juta", "miliar", "triliun"] as const;

/** Batas atas (eksklusif) yang bisa dieja: seribu triliun. */
export const BATAS_TERBILANG = 1e15;

const gabung = (...kata: string[]): string => kata.filter((k) => k !== "").join(" ");

// noUncheckedIndexedAccess membuat SATUAN[i] bertipe string | undefined.
// Indeks kita selalu 0..11, jadi `?? ""` cukup ditulis sekali di sini.
const satuan = (i: number): string => SATUAN[i] ?? "";

// n selalu 0..999.
function ratusan(n: number): string {
  if (n < 12) return satuan(n);
  if (n < 20) return gabung(satuan(n - 10), "belas");
  if (n < 100) return gabung(satuan(Math.floor(n / 10)), "puluh", satuan(n % 10));
  if (n < 200) return gabung("seratus", ratusan(n - 100));
  return gabung(satuan(Math.floor(n / 100)), "ratus", ratusan(n % 100));
}

/**
 * Mengeja bilangan bulat dalam bahasa Indonesia, misalnya untuk kuitansi.
 *
 * @param n - Bilangan bulat, `-999.999.999.999.999` sampai `999.999.999.999.999`.
 * @returns Ejaan huruf kecil dengan satu spasi antarkata.
 * @throws `RangeError` kalau `n` bukan bilangan bulat atau di luar batas {@link BATAS_TERBILANG}.
 *
 * @example
 * ```ts
 * terbilang(1250000); // "satu juta dua ratus lima puluh ribu"
 * terbilang(1001); // "seribu satu"
 * ```
 */
export function terbilang(n: number): string {
  if (!Number.isInteger(n) || Math.abs(n) >= BATAS_TERBILANG) {
    throw new RangeError(`terbilang: butuh bilangan bulat di bawah seribu triliun, bukan ${String(n)}`);
  }
  if (n === 0) return "nol";
  if (n < 0) return `minus ${terbilang(-n)}`;

  const bagian: string[] = [];
  for (let sisa = n, skala = 0; sisa > 0; sisa = Math.floor(sisa / 1000), skala++) {
    const kelompok = sisa % 1000;
    if (kelompok === 0) continue;
    bagian.unshift(skala === 1 && kelompok === 1 ? "seribu" : gabung(ratusan(kelompok), SKALA[skala] ?? ""));
  }
  return bagian.join(" ");
}

import fc from "fast-check";
import { describe, expect, it } from "vitest";
import { BATAS_TERBILANG, terbilang } from "../src/terbilang.js";

describe("terbilang", () => {
  it.each([
    [0, "nol"],
    [1, "satu"],
    [10, "sepuluh"],
    [11, "sebelas"],
    [12, "dua belas"],
    [20, "dua puluh"],
    [21, "dua puluh satu"],
    [100, "seratus"],
    [111, "seratus sebelas"],
    [205, "dua ratus lima"],
    [1000, "seribu"],
    [1001, "seribu satu"],
    [2000, "dua ribu"],
    [21000, "dua puluh satu ribu"],
    [1000000, "satu juta"],
    [1250000, "satu juta dua ratus lima puluh ribu"],
    [1000000000, "satu miliar"],
    [1000000000000, "satu triliun"],
    [-7, "minus tujuh"],
  ])("%d dieja %s", (n, harapan) => {
    expect(terbilang(n)).toBe(harapan);
  });

  it("menolak pecahan, NaN, dan angka terlalu besar", () => {
    expect(() => terbilang(1.5)).toThrow(RangeError);
    expect(() => terbilang(Number.NaN)).toThrow(RangeError);
    expect(() => terbilang(BATAS_TERBILANG)).toThrow(RangeError);
  });
});

const bilangan = fc.integer({ min: -(BATAS_TERBILANG - 1), max: BATAS_TERBILANG - 1 });

describe("properti terbilang", () => {
  it("selalu huruf kecil dengan tepat satu spasi antarkata", () => {
    fc.assert(
      fc.property(bilangan, (n) => {
        expect(terbilang(n)).toMatch(/^[a-z]+( [a-z]+)*$/);
      }),
    );
  });

  it("bilangan negatif = minus + ejaan positifnya", () => {
    fc.assert(
      fc.property(fc.integer({ min: 1, max: BATAS_TERBILANG - 1 }), (n) => {
        expect(terbilang(-n)).toBe(`minus ${terbilang(n)}`);
      }),
    );
  });

  it("tidak pernah menulis 'satu ratus', 'satu puluh', atau 'satu belas'", () => {
    fc.assert(
      fc.property(bilangan, (n) => {
        expect(terbilang(n)).not.toMatch(/(^| )satu (ratus|puluh|belas)/);
      }),
    );
  });
});

/** Jenis kelamin yang tersirat di NIK. */
export type JenisKelamin = "laki-laki" | "perempuan";

/** Bagian-bagian yang bisa dibaca dari NIK. */
export interface DataNik {
  /** 2 digit kode provinsi, misalnya `"32"`. */
  readonly kodeProvinsi: string;
  /** 4 digit kode kabupaten/kota, misalnya `"3273"`. */
  readonly kodeKabupatenKota: string;
  /** 6 digit kode kecamatan, misalnya `"327301"`. */
  readonly kodeKecamatan: string;
  readonly jenisKelamin: JenisKelamin;
  /** Tanggal lahir. NIK hanya menyimpan 2 digit tahun, jadi abadnya tidak bisa dipastikan. */
  readonly tanggalLahir: {
    readonly hari: number;
    readonly bulan: number;
    readonly tahunDuaDigit: number;
  };
  /** 4 digit nomor urut, `"0001"` sampai `"9999"`. */
  readonly nomorUrut: string;
}

/** Hasil {@link parseNik}: berhasil dengan data, atau gagal dengan alasan. */
export type HasilNik =
  | { readonly ok: true; readonly data: DataNik }
  | { readonly ok: false; readonly alasan: string };

const gagal = (alasan: string): HasilNik => ({ ok: false, alasan });

/**
 * Memeriksa **format** NIK (Nomor Induk Kependudukan) dan membaca bagian-bagiannya.
 *
 * Hanya bentuknya yang diperiksa: 16 digit, kode wilayah tidak nol, tanggal lahir masuk akal
 * (perempuan: tanggal + 40), dan nomor urut bukan `0000`. Fungsi ini **tidak** bisa memastikan
 * NIK itu benar-benar terdaftar di Dukcapil.
 *
 * @param nik - NIK, boleh mengandung spasi.
 * @returns `{ ok: true, data }` atau `{ ok: false, alasan }`. Tidak pernah melempar error.
 *
 * @example
 * ```ts
 * const hasil = parseNik("3273015708950001"); // contoh palsu
 * if (hasil.ok) console.log(hasil.data.jenisKelamin); // "perempuan"
 * ```
 */
export function parseNik(nik: string): HasilNik {
  const angka = nik.replace(/\s/g, "");
  if (!/^\d{16}$/.test(angka)) return gagal("NIK harus 16 digit angka");

  const dua = (mulai: number): number => Number(angka.slice(mulai, mulai + 2));
  if (dua(0) < 11) return gagal("kode provinsi tidak dikenal");
  if (dua(2) === 0 || dua(4) === 0) return gagal("kode kabupaten/kota atau kecamatan tidak boleh 00");

  const tanggal = dua(6);
  const perempuan = tanggal > 40;
  const hari = perempuan ? tanggal - 40 : tanggal;
  const bulan = dua(8);
  const tahunDuaDigit = dua(10);
  if (bulan < 1 || bulan > 12) return gagal("bulan lahir harus 01 sampai 12");
  // Tahun 2000 + yy dipakai karena kabisatnya mencakup 19yy juga (kecuali 1900, yang terlalu tua untuk NIK).
  const hariDalamBulan = new Date(Date.UTC(2000 + tahunDuaDigit, bulan, 0)).getUTCDate();
  if (hari < 1 || hari > hariDalamBulan) return gagal("tanggal lahir tidak ada di kalender");

  const nomorUrut = angka.slice(12);
  if (nomorUrut === "0000") return gagal("nomor urut tidak boleh 0000");

  return {
    ok: true,
    data: {
      kodeProvinsi: angka.slice(0, 2),
      kodeKabupatenKota: angka.slice(0, 4),
      kodeKecamatan: angka.slice(0, 6),
      jenisKelamin: perempuan ? "perempuan" : "laki-laki",
      tanggalLahir: { hari, bulan, tahunDuaDigit },
      nomorUrut,
    },
  };
}

/**
 * Versi singkat {@link parseNik} kalau kamu hanya butuh ya atau tidak.
 *
 * @param nik - NIK yang diperiksa.
 * @returns `true` kalau formatnya sah.
 */
export function validasiNik(nik: string): boolean {
  return parseNik(nik).ok;
}

import fc from "fast-check";
import { describe, expect, it } from "vitest";
import { parseNik, validasiNik, type DataNik } from "../src/nik.js";

// Semua NIK di sini palsu, disusun dari kode wilayah contoh. Jangan pernah memakai NIK asli di tes.
describe("parseNik", () => {
  it("membaca NIK perempuan (tanggal + 40)", () => {
    expect(parseNik("3273015708950001")).toEqual({
      ok: true,
      data: {
        kodeProvinsi: "32",
        kodeKabupatenKota: "3273",
        kodeKecamatan: "327301",
        jenisKelamin: "perempuan",
        tanggalLahir: { hari: 17, bulan: 8, tahunDuaDigit: 95 },
        nomorUrut: "0001",
      },
    });
  });

  it("menerima spasi dan membaca NIK laki-laki", () => {
    const hasil = parseNik("3273 0129 0200 0123");
    expect(hasil.ok && hasil.data.jenisKelamin).toBe("laki-laki");
    expect(hasil.ok && hasil.data.tanggalLahir).toEqual({ hari: 29, bulan: 2, tahunDuaDigit: 0 });
  });

  it.each([
    ["327301570895000", "NIK harus 16 digit angka"],
    ["32730157089500a1", "NIK harus 16 digit angka"],
    ["0973015708950001", "kode provinsi tidak dikenal"],
    ["3200015708950001", "kode kabupaten/kota atau kecamatan tidak boleh 00"],
    ["3273005708950001", "kode kabupaten/kota atau kecamatan tidak boleh 00"],
    ["3273015713950001", "bulan lahir harus 01 sampai 12"],
    ["3273013102950001", "tanggal lahir tidak ada di kalender"],
    ["3273012902950001", "tanggal lahir tidak ada di kalender"],
    ["3273013508950001", "tanggal lahir tidak ada di kalender"],
    ["3273015708950000", "nomor urut tidak boleh 0000"],
  ])("menolak %s: %s", (nik, alasan) => {
    expect(parseNik(nik)).toEqual({ ok: false, alasan });
    expect(validasiNik(nik)).toBe(false);
  });
});

// Generator: bagian-bagian NIK yang sah, lalu disusun jadi string 16 digit.
const dataNik: fc.Arbitrary<DataNik> = fc
  .record({
    prov: fc.integer({ min: 11, max: 99 }),
    kab: fc.integer({ min: 1, max: 99 }),
    kec: fc.integer({ min: 1, max: 99 }),
    tanggal: fc.date({ min: new Date("1940-01-01"), max: new Date("2039-12-31"), noInvalidDate: true }),
    perempuan: fc.boolean(),
    urut: fc.integer({ min: 1, max: 9999 }),
  })
  .map(({ prov, kab, kec, tanggal, perempuan, urut }) => {
    const p = (n: number, panjang = 2): string => String(n).padStart(panjang, "0");
    const wilayah = p(prov) + p(kab) + p(kec);
    return {
      kodeProvinsi: wilayah.slice(0, 2),
      kodeKabupatenKota: wilayah.slice(0, 4),
      kodeKecamatan: wilayah,
      jenisKelamin: perempuan ? "perempuan" : "laki-laki",
      tanggalLahir: {
        hari: tanggal.getUTCDate(),
        bulan: tanggal.getUTCMonth() + 1,
        tahunDuaDigit: tanggal.getUTCFullYear() % 100,
      },
      nomorUrut: p(urut, 4),
    };
  });

function susunNik(d: DataNik): string {
  const p = (n: number): string => String(n).padStart(2, "0");
  const { hari, bulan, tahunDuaDigit } = d.tanggalLahir;
  const kodeHari = d.jenisKelamin === "perempuan" ? hari + 40 : hari;
  return d.kodeKecamatan + p(kodeHari) + p(bulan) + p(tahunDuaDigit) + d.nomorUrut;
}

describe("properti NIK", () => {
  it("susun lalu parse mengembalikan data yang sama", () => {
    fc.assert(
      fc.property(dataNik, (data) => {
        expect(parseNik(susunNik(data))).toEqual({ ok: true, data });
      }),
    );
  });

  it("tidak pernah melempar error untuk teks apa pun", () => {
    fc.assert(
      fc.property(fc.string(), (teks) => {
        expect(typeof validasiNik(teks)).toBe("boolean");
      }),
    );
  });
});

// @ts-check
import js from "@eslint/js";
import { defineConfig } from "eslint/config";
import tseslint from "typescript-eslint";

export default defineConfig(
  { ignores: ["dist/", "coverage/", "docs/", ".smoke/"] },
  js.configs.recommended,
  tseslint.configs.strictTypeChecked,
  tseslint.configs.stylisticTypeChecked,
  {
    languageOptions: {
      parserOptions: {
        projectService: true,
        tsconfigRootDir: import.meta.dirname,
      },
    },
  },
  {
    // Berkas .js/.cjs/.mjs tidak masuk tsconfig, jadi aturan yang butuh info tipe dimatikan.
    files: ["**/*.{js,cjs,mjs}"],
    extends: [tseslint.configs.disableTypeChecked],
  },
  {
    // Berkas uji asap dijalankan langsung oleh Node, jadi boleh memakai require dan console.
    files: ["smoke/**"],
    languageOptions: { globals: { require: "readonly", console: "readonly" } },
    rules: { "@typescript-eslint/no-require-imports": "off" },
  },
);

import assert from "node:assert/strict";
import { formatRupiah, parseNik, terbilang } from "@namamu/idn-kit";
import { parseRupiah } from "@namamu/idn-kit/rupiah";

assert.equal(formatRupiah(1500000), "Rp 1.500.000");
assert.equal(parseRupiah("Rp 1.500.000"), 1500000);
